insert into public.questions(id,title,prompt,options,explanation,category,xp,subject_id,kind,payload,activity_type) values('00000000-0000-4000-8000-000000013043','Limites de confiança','Avalie cada afirmação.','["A validação do formulário no navegador substitui a validação no servidor.","O servidor deve conferir se a pessoa pode alterar o produto solicitado.","Um erro de validação pode indicar qual campo precisa de correção sem revelar dados internos."]','Dados do navegador podem ser alterados. Validação e autorização precisam ocorrer no servidor.','Prática guiada','40','00000000-0000-4000-8000-000000000014','true_false','{"statements":["A validação do formulário no navegador substitui a validação no servidor.","O servidor deve conferir se a pessoa pode alterar o produto solicitado.","Um erro de validação pode indicar qual campo precisa de correção sem revelar dados internos."]}','true_false') on conflict(id) do nothing;
